create or replace function public.crm_experiment_report(p_experiment_id uuid) returns jsonb language sql stable set search_path=public as $fn$
with e as(select id from public.crm_experiments where id=p_experiment_id and user_id=auth.uid()),v as(select v.id,v.name,v.weight,count(distinct x.subject_key)::int exposures,count(distinct case when o.outcome in ('converted','conversion') then o.subject_key end)::int conversions,coalesce(sum(case when o.outcome='revenue' then o.value else 0 end),0) revenue from public.crm_experiment_variants v join e on e.id=v.experiment_id left join public.crm_experiment_exposures x on x.variant_id=v.id left join public.crm_experiment_outcomes o on o.variant_id=v.id and o.subject_key=x.subject_key group by v.id,v.name,v.weight),s as(select v.*,case when exposures>0 then conversions::numeric/exposures else 0 end rate from v),ci as(select s.*,case when exposures>0 then (rate+1.96^2/(2*exposures)-1.96*sqrt((rate*(1-rate)+1.96^2/(4*exposures))/exposures))/(1+1.96^2/exposures) else 0 end lower95,case when exposures>0 then (rate+1.96^2/(2*exposures)+1.96*sqrt((rate*(1-rate)+1.96^2/(4*exposures))/exposures))/(1+1.96^2/exposures) else 0 end upper95 from s),g as(select coalesce(max(min_sample_size),100)::int min_sample,coalesce(max(max_regression),0)::numeric max_regression from public.crm_experiment_guardrails where experiment_id=p_experiment_id and enabled),base as(select rate baseline_rate from ci order by name limit 1),eligible as(select ci.* from ci cross join g cross join base where ci.exposures>=g.min_sample and (g.max_regression<=0 or ci.rate>=base.baseline_rate*(1-g.max_regression))),best as(select * from eligible order by rate desc,revenue desc,id limit 1),totals as(select coalesce(sum(exposures),0)::int exposures,coalesce(sum(conversions),0)::int conversions,coalesce(sum(revenue),0) revenue from s)
select jsonb_build_object('experiment_id',p_experiment_id,'variants',coalesce((select jsonb_agg(jsonb_build_object('variant_id',ci.id,'name',ci.name,'weight',ci.weight,'exposures',ci.exposures,'conversions',ci.conversions,'conversion_rate',round(ci.rate,6),'revenue',ci.revenue,'ci95_lower',round(ci.lower95,6),'ci95_upper',round(ci.upper95,6),'eligible_for_winner',exists(select 1 from eligible z where z.id=ci.id)) order by ci.name) from ci),'[]'::jsonb),'totals',(select to_jsonb(totals) from totals),'guardrails',jsonb_build_object('minimum_sample_size',(select min_sample from g),'max_regression',(select max_regression from g),'winner_eligible',(select count(*)>0 from best)),'learning',coalesce((select jsonb_agg(jsonb_build_object('variant_id',ci.id,'name',ci.name,'conversion_rate',round(ci.rate,6),'sample_size',ci.exposures,'ci95_lower',round(ci.lower95,6),'ci95_upper',round(ci.upper95,6),'confidence_level','95_percent_wilson_descriptive') order by ci.rate desc) from ci),'[]'::jsonb),'recommended_variant',(select jsonb_build_object('variant_id',best.id,'name',best.name,'conversion_rate',round(best.rate,6),'ci95_lower',round(best.lower95,6),'ci95_upper',round(best.upper95,6),'reason','Maior conversão observada entre variantes elegíveis pelos guardrails de amostra e regressão; Wilson 95% descritivo, sem alegação causal.') from best),'generated_at',now());
$fn$;
